const isSeparatorRow = (line: string): boolean => {
  const cells = parseRow(line);
  return cells.length > 0 && cells.every((cell) => /^:?-+:?$/.test(cell));
};

const CALLOUT_LINE_RE = /^> \*\*(.+?)\*\* — (.+)$/u;

