describe("the js-requirement callout", () => {
  const page = [
    "# CSS: alert",
    "",
    "Summary.",
    "",
    JS_CALLOUT_MARKER,
    "> [!TIP]",
    "> **JS Enhancement** — Pair it with `@pantoken/interactions`. See the [modifier table below](#modifiers).",
    "",
    "## Modifiers",
    "",
  ].join("\n");

