      kind === "glossary" ? "JS-bővítmény" : "Párosítsd a `@pantoken/interactions`-szal.";
    const out = reassemble(segmentMarkdown(page), resolve);
    expect(out).toContain("> **JS-bővítmény** — Párosítsd a `@pantoken/interactions`-szal.");
  });

