/** A generated Markdown unit's stable prose template and its verbatim code bindings. */
export interface GeneratedMarkdown {
  template: string;
  values: readonly string[];
}
interface GeneratedOptions {
  tables?: boolean;
  tableValuesOnly?: boolean;
}

