        .replace(">Primary</button>", ">Primær</button>")
        .replace(">Secondary</button>", ">Sekundær</button>"),
    );
  });

  test("non-html and unclosed html fences remain preserved", () => {
    const page = ["```css", ".Primary {}", "```", "", "```html", "<p>Primary</p>"].join("\n");
    const segments = segmentMarkdown(page);

    expect(segments.some((segment) => segment.kind === "html")).toBe(false);
    expect(collectUnits(segments)).toEqual([]);
    expect(reassemble(segments, () => "TRANSLATED")).toBe(page);
  });

  test("tables become table segments", () => {
    const tables = cssdoc.filter((s) => s.kind === "table");
    expect(tables.length).toBe(2);
  });

  test("a standalone -flag paragraph (e.g. -nocard before an @example fence) is preserved", () => {
    const page = ["## Examples", "", "-nocard", "```html", "<div></div>", "```", ""].join("\n");
    const segments = segmentMarkdown(page);
    expect(find(segments, "-nocard").kind).toBe("preserve");
    expect(reassemble(segments, identity)).toBe(page);
  });

  test("multiple -flag tokens on one line are also preserved", () => {
    expect(find(segmentMarkdown("-nocard -noshow\n"), "-nocard -noshow").kind).toBe("preserve");
  });

  test.each(["-automatica11y", "-automatica11y -canvas-rce"])(
    "keeps %s fixture text outside the translation catalog",
    (flags) => {
      const page = `${flags}\n\`\`\`html\n<label>Audit-only label<input></label>\n\`\`\`\n`;
      const segments = segmentMarkdown(page);
      expect(collectUnits(segments)).toEqual([]);
      expect(reassemble(segments, identity)).toBe(page);
    },
