      closing: "```",
    });
    expect(collectUnits(segments)).toContainEqual({
      kind: "prose",
      text: "Ask the agent to set up pantoken.",
    });
    expect(reassemble(segments, (text) => `HU: ${text}`)).toContain(
      "```prompt\nHU: Ask the agent to set up pantoken.\n```",
    );
  });

