          .slice(1, -1)
          .split(/(?<!\\)\|/u)
          .map((cell) => cell.trim());
      const separator = (value: string): boolean =>
        value.startsWith("|") && cells(value).every((cell) => /^:?-+:?$/u.test(cell));
