 *
 * @module
 */

import {
  type DemoSegment,
  collectDemoUnits,
  reassembleDemoHtml,
  segmentDemoHtml,
} from "./segment-demo-html.ts";
import { resolveExampleTargets } from "@pantoken/utils/example-targets";
import {
  GENERATED_VALUES_MARKER,
  generatedMarkdown,
