    return match.startsWith("</") ? `&lt;/${name}&gt;` : `&lt;${name}&gt;`;
  });
  for (const [index, block] of preserved.entries()) {
    escaped = escaped.replaceAll(`__PTK_HTML_SAFE_${index}__`, block);
  }
  return escaped;
};

