sources.scriptContent:
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";
import { parsePo, type PoEntry } from "@pantoken/i18n-engine";
import {
  generatedFileMarkdown,
  restoreGeneratedMarkdown,
} from "../../tools/translation-adapters/src/generated-values.ts";
import { formatMarkdown } from "../../scripts/release/format-markdown.ts";
import { runAsMain } from "../../scripts/release/cli.ts";
import { GlossaryTranslationAdapter } from "./api-translation.ts";
import { collectUnits, reassemble, segmentMarkdown, type Resolve } from "./segment-markdown.ts";
import { walkFiles } from "./lib/files.ts";
import { NON_ROOT_LOCALES, parseRequestedLocales } from "../.vitepress/i18n.ts";
import { escapeBareHtmlTags } from "./markdown-structure.ts";

/** Render from reviewed catalog entries only; a cache-only refresh must never hide translation gaps. */
export function catalogResolver(entries: readonly PoEntry[]): Resolve {
  const translations = new Map(
    entries
      .filter((entry) => !entry.obsolete && !entry.fuzzy && entry.msgstr !== "")
      .map((entry) => [`${entry.msgctxt ?? ""}\0${entry.msgid}`, entry.msgstr]),
  );
  return (source, kind) => {
    const translated = translations.get(`docs.api:${kind}\0${source}`);
    if (translated === undefined)
      throw new Error(`Missing reviewed generated-doc translation: ${source.slice(0, 100)}`);
    return translated;
  };
}

/** Refresh current machine values without invoking a translation provider or changing any catalog. */
export async function renderGeneratedValues(
  options: {
    guidesOnly?: boolean;
    check?: boolean;
  } = {},
): Promise<void> {
  const root = join(import.meta.dirname, "../..");
  const docs = join(root, "docs");
  const locales = parseRequestedLocales(process.env.DOCS_TRANSLATION_LOCALE, NON_ROOT_LOCALES);
  const compatibility = generatedFileMarkdown(readFileSync(join(docs, "compatibility.md"), "utf8"));
  const pending: Array<{ path: string; content: string }> = [];
  const stage = (path: string, content: string): void => {
    if (!existsSync(path) || readFileSync(path, "utf8") !== content)
      pending.push({ path, content });
  };

  for (const locale of locales) {
    const guides = parsePo(readFileSync(join(root, "l10n", locale, "docs.guides.po"), "utf8"));
    const guide = guides.find(
      (entry) =>
        !entry.obsolete &&
        !entry.fuzzy &&
        entry.msgid === compatibility.template &&
        entry.msgstr !== "",
    );
    if (!guide) throw new Error(`${locale}: missing reviewed compatibility translation`);
    const guidePath = join(docs, locale, "compatibility.md");
    stage(
      guidePath,
      await formatMarkdown(restoreGeneratedMarkdown(guide.msgstr, compatibility), guidePath),
    );
    if (options.guidesOnly) continue;

    const entries = parsePo(readFileSync(join(root, "l10n", locale, "docs.api.po"), "utf8"));
    const resolveProse = catalogResolver(entries);
    const glossary = new GlossaryTranslationAdapter(locale);
    for (const path of walkFiles(join(docs, "api")).filter((file) => file.endsWith(".md"))) {
      const source = readFileSync(path, "utf8");
      const segments = segmentMarkdown(source, { scope: relative(join(docs, "api"), path) });
      const terms = new Map<string, string>();
      for (const unit of collectUnits(segments)) {
        if (unit.kind === "glossary") terms.set(unit.text, await glossary.translateText(unit.text));
      }
      try {
        const content = reassemble(segments, (text, kind) =>
          kind === "glossary" ? (terms.get(text) ?? text) : escapeBareHtmlTags(resolveProse(text, kind)),
        ).replace(/(\]\(|href=")\/api(?=[/")])/gu, `$1/${locale}/api`);
        stage(join(docs, locale, relative(docs, path)), content);
      } catch (error) {
        throw new Error(`${locale} ${relative(docs, path)}: ${String(error)}`, { cause: error });
      }
    }
  }
  if (options.check && pending.length > 0) {
    throw new Error(
      `Generated values are stale in ${pending.length} locale pages; run docs:values:render`,
    );
  }
  if (!options.check) for (const file of pending) writeFileSync(file.path, file.content);
  console.log(
    `Generated values: ${pending.length} page(s) ${options.check ? "stale" : "updated"}; no provider calls`,
  );
}

runAsMain(import.meta.url, async () => {
  const args = process.argv.slice(2);
  for (const arg of args)
    if (!["--guides-only", "--check"].includes(arg)) throw new Error(`Unknown argument: ${arg}`);
  await renderGeneratedValues({
    guidesOnly: args.includes("--guides-only"),
    check: args.includes("--check"),
  });
});

import { globSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import {
  parsePo,
  serializePo,
  writeCatalog,
  type PoEntry,
} from "../../tools/i18n-engine/src/po.ts";
import {
  GENERATED_VALUES_MARKER,
  assertGeneratedTranslation,
  generatedMarkdown,
  migrateGeneratedMarkdown,
  restoreGeneratedMarkdown,
  scopeGeneratedMarkdown,
} from "../../tools/translation-adapters/src/generated-values.ts";
import { runAsMain } from "./cli.ts";
import { loadConfig } from "../../tools/i18n-engine/src/config.ts";
import { segmentMarkdown } from "../../docs/scripts/segment-markdown.ts";

/** Prepare one catalog migration atomically. Ambiguous values require a reviewed manual mapping. */
export function migrateGeneratedCatalog(
  entries: readonly PoEntry[],
  namespace: "api" | "guides",
  generatedTemplates?: ReadonlyMap<string, ReadonlySet<string>>,
): PoEntry[] {
  const output = new Map<string, PoEntry>();
  const candidates = entries.flatMap(
    (entry): Array<{ entry: PoEntry; scope?: string; skip?: boolean }> => {
      if (namespace !== "api" || generatedTemplates === undefined || entry.obsolete)
        return [{ entry }];
      if (entry.msgid.startsWith("<!-- pantoken-value-scope:")) {
        if (!entry.fuzzy && entry.msgstr !== "")
          assertGeneratedTranslation(entry.msgid, entry.msgstr);
        return [{ entry, skip: true }];
      }
      const template = entry.msgid.includes("{{ptk_code_")
        ? entry.msgid
        : generatedMarkdown(entry.msgid).template;
      const matched = entry.references.filter((reference) =>
        generatedTemplates.get(reference)?.has(template),
      );
      if (matched.length === 0) return [{ entry, skip: true }];
      const remaining = entry.references.filter((reference) => !matched.includes(reference));
      return [
        ...matched.map((scope) => ({ entry: { ...entry, references: [scope] }, scope })),
        ...(remaining.length > 0
          ? [{ entry: { ...entry, references: remaining }, skip: true }]
          : []),
      ];
    },
  );
  for (const { entry, scope, skip } of candidates) {
    const compatibility = namespace === "guides" && entry.references.includes("compatibility.md");
    const eligible =
      !skip &&
      !entry.obsolete &&
      (compatibility || (namespace === "api" && entry.msgctxt === "docs.api:prose"));
    let updated = entry;
    if (eligible) {
      try {
        const source = entry.msgid.replace(`${GENERATED_VALUES_MARKER}\n`, "");
        const options = compatibility ? { tables: true, tableValuesOnly: true } : {};
        if (source.includes("{{ptk_code_")) {
          assertGeneratedTranslation(
            source,
            entry.msgstr !== "" && !entry.fuzzy ? entry.msgstr : source,
          );
          updated = entry;
        } else {
          const literal = generatedMarkdown(source, options);
          const generated = scopeGeneratedMarkdown(literal, scope);
          const translation =
            entry.msgstr === "" || entry.fuzzy
              ? entry.msgstr
              : migrateGeneratedMarkdown(source, entry.msgstr, options);
          const prefix = generated.template.slice(
            0,
            generated.template.length - literal.template.length,
          );
          const scopedTranslation =
            translation === "" || entry.fuzzy ? translation : prefix + translation;
          if (entry.msgstr !== "" && !entry.fuzzy)
            restoreGeneratedMarkdown(scopedTranslation, generated);
          updated = { ...entry, msgid: generated.template, msgstr: scopedTranslation };
        }
      } catch (error) {
        throw new Error(
          `${entry.references.join(", ")}: ${entry.msgid.slice(0, 100)}: ${String(error)}`,
          { cause: error },
        );
      }
    }
    const key = `${updated.obsolete}\0${updated.msgctxt ?? ""}\0${updated.msgid}`;
    const existing = output.get(key);
    if (existing && existing.msgstr !== updated.msgstr)
      throw new Error(`Conflicting translations for template: ${updated.msgid.slice(0, 100)}`);
    output.set(
      key,
      existing
        ? { ...existing, references: [...new Set([...existing.references, ...updated.references])] }
        : updated,
    );
  }
  return [...output.values()];
}

runAsMain(import.meta.url, async () => {
  const args = process.argv.slice(2);
  if (args.length > 1 || (args[0] !== "--check" && args[0] !== "--write"))
    throw new Error("Usage: migrate-generated-values.ts --check|--write");
  const l10n = join(import.meta.dirname, "../../l10n");
  const root = join(import.meta.dirname, "../..");
  const config = loadConfig(join(root, "i18n.config.json"));
  const generatedTemplates = new Map<string, Set<string>>();
  for (const file of globSync("docs/api/**/*.md", { cwd: root })) {
    const templates = new Set<string>();
    for (const segment of segmentMarkdown(readFileSync(join(root, file), "utf8"))) {
      if (segment.kind === "callout") templates.add(generatedMarkdown(segment.note).template);
      if (segment.kind === "prose" && segment.generatedValues)
        templates.add(generatedMarkdown(segment.text).template);
    }
    if (templates.size > 0) generatedTemplates.set(file.slice("docs/api/".length), templates);
  }
  if (generatedTemplates.size === 0)
    throw new Error("Generate English API documentation before migrating value bindings");
  const pending: Array<{ path: string; catalog: string }> = [];
  const failures: string[] = [];
  const directories = [
    "",
    ...readdirSync(l10n, { withFileTypes: true })
      .filter((entry) => entry.isDirectory() && entry.name !== config.source)
      .map((entry) => entry.name),
  ];
  for (const directory of directories) {
    for (const namespace of ["api", "guides"] as const) {
      const path = join(l10n, directory, `docs.${namespace}.${directory ? "po" : "pot"}`);
      try {
        const source = readFileSync(path, "utf8");
        pending.push({
          path,
          catalog: serializePo(
            migrateGeneratedCatalog(parsePo(source), namespace, generatedTemplates),
          ),
        });
      } catch (error) {
        failures.push(`${path}: ${String(error)}`);
      }
    }
  }
  if (failures.length > 0) throw new Error(`No catalogs changed:\n${failures.join("\n")}`);
  if (args[0] === "--write") for (const file of pending) writeCatalog(file.path, file.catalog);
  console.log(
    `Generated-value migration: ${pending.length} catalogs ${args[0] === "--write" ? "written" : "validated"}`,
  );
});

/**
 * Detect translation drift: English content whose translation is missing or stale.
 *
 * The committed translation catalogs under `/l10n` are keyed by source identity; legacy JSON memory
 * remains only for surfaces not yet migrated.
 * — a unit's key is `sha256(kind \0 source)`. So the key for a block of *current* English is present
 * only if that exact text was translated (and the prose poison-cache guard means a prose key is only
 * ever written by a real `:claude` run, never by the glossary passthrough). Edit the English and its
 * hash changes, so the old entry no longer matches: a missing key == untranslated or drifted.
 *
 * This check derives the keys the current English needs and asserts each is in its catalog. It is
 * adapter-free — it never constructs an adapter or spawns `claude` — so it is safe to run in CI
 * (`docs/conventions/build-and-docs.md`: never wire the `:claude` cold pass into CI). Fill drift
 * locally with `vp run docs:locales:translate`, then commit the updated cache.
 *
 * Guides drift is pure (the English source is committed). API drift needs the generated EN tree
 * (`docs/api/**`), so run it after `docs:api:en`; if `docs/api` is absent it is skipped with a note.
 *
 * Whether a given miss blocks the merge or only warns is decided by `i18n.config.json`, per surface
 * (`docs.guides`, `docs.api`, `docs.home`, `docs.chrome`, `docs.demos`) and per
 * locale tier — so adding an English guide doesn't have to wait on ~90 translations. See
 * `tools/translation-adapters/src/drift-policy.ts`.
 *
 * @module
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { DriftReporter, type DriftUnit } from "@pantoken/translation-adapters";
import { extractFrontmatterUnits, parsePo } from "@pantoken/i18n-engine";
import { ENGLISH_UI_STRINGS, NON_ROOT_LOCALES, flattenStrings } from "../.vitepress/i18n.ts";
import { GLOSSARY_TERMS } from "./glossary.ts";
import { listDemoNames, loadDemoI18n } from "./demo-i18n.ts";
import { collectUnits, isCatalogedApiUnit, segmentMarkdown } from "./segment-markdown.ts";
import { keyFor } from "./translation-memory.ts";
import {
  assertGeneratedTranslation,
  generatedFileMarkdown,
} from "../../tools/translation-adapters/src/generated-values.ts";

const docsRoot = join(import.meta.dirname, "..");
const cacheDir = join(docsRoot, "i18n-cache");
const guideDir = join(docsRoot, "guide");
const demoDir = join(docsRoot, "demos");
const apiDir = join(docsRoot, "api");
const homeIndex = join(docsRoot, "index.md");
const l10nDir = join(docsRoot, "..", "l10n");

const targets = NON_ROOT_LOCALES;

interface Missing {
  file: string;
  kind: string;
  sample: string;
  unit?: DriftUnit;
}

const loadPoTranslatedSet = (
  poPath: string,
  keyFn: (entry: { msgctxt?: string; msgid: string; msgstr: string }) => string | undefined = (
    entry,
  ) => entry.msgid,
): Set<string | undefined> => {
  return new Set(
    parsePo(readFileSync(poPath, "utf8"))
      .filter((entry) => !entry.obsolete && !entry.fuzzy && entry.msgstr !== "")
      .map((entry) => {
        if (entry.msgid.includes("{{ptk_code_"))
          assertGeneratedTranslation(entry.msgid, entry.msgstr);
        return entry;
      })
      .map(keyFn),
  );
};

const loadCacheKeys = (locale: string, namespace: string): Set<string> => {
  const path = join(cacheDir, `${locale}.${namespace}.json`);
  if (!existsSync(path)) return new Set();
  const parsed = JSON.parse(readFileSync(path, "utf8")) as { entries?: Record<string, string> };
  return new Set(Object.keys(parsed.entries ?? {}));
};

/** Recursively collect every `.md` file under `dir` (returns `[]` when `dir` doesn't exist). */
export const walkMarkdown = (dir: string): string[] => {
  if (!existsSync(dir)) return [];
  const out: string[] = [];
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) out.push(...walkMarkdown(full));
    else if (full.endsWith(".md")) out.push(full);
  }
  return out;
};

const preview = (text: string): string =>
  text.replace(/\s+/g, " ").trim().slice(0, 60) + (text.length > 60 ? "…" : "");

/** Guide drift: each guide and the compatibility page is one whole-file `markdown` unit. */
const guideDrift = (locale: string): Missing[] => {
  const poPath = join(l10nDir, locale, "docs.guides.po");
  const guideFiles = [...walkMarkdown(guideDir), join(docsRoot, "compatibility.md")].filter(
    existsSync,
  );
  if (existsSync(poPath)) {
    const translated = loadPoTranslatedSet(poPath);
    return guideFiles
      .map((file) => ({
        file: relative(docsRoot, file),
        source: generatedFileMarkdown(readFileSync(file, "utf8")).template,
      }))
      .filter(({ source }) => !translated.has(source))
      .map(({ file, source }) => ({
        file,
        kind: "markdown",
        sample: preview(source),
        unit: { msgid: source },
      }));
  }
  const cached = loadCacheKeys(locale, "guides");
  const missing: Missing[] = [];
  for (const file of guideFiles) {
    const source = generatedFileMarkdown(readFileSync(file, "utf8")).template;
    if (!cached.has(keyFor("markdown", source))) {
      missing.push({
        file: relative(docsRoot, file),
        kind: "markdown",
        sample: preview(source),
        unit: { msgid: source },
      });
    }
  }
  return missing;
};

/** API drift: every `prose` block across the generated EN tree needs a cached `:claude` translation. */
export const apiDrift = (locale: string): Missing[] => {
  const poPath = join(l10nDir, locale, "docs.api.po");
  if (existsSync(poPath)) {
    const translated = loadPoTranslatedSet(
      poPath,
      (entry) => `${entry.msgctxt ?? ""}\0${entry.msgid}`,
    );
    const missing: Missing[] = [];
    for (const file of walkMarkdown(apiDir)) {
      for (const unit of collectUnits(
        segmentMarkdown(readFileSync(file, "utf8"), { scope: relative(apiDir, file) }),
      )) {
        if (!isCatalogedApiUnit(unit)) continue;
        if (!translated.has(`docs.api:${unit.kind}\0${unit.text}`)) {
          missing.push({
            file: relative(docsRoot, file),
            kind: unit.kind,
            sample: preview(unit.text),
            unit: { msgctxt: `docs.api:${unit.kind}`, msgid: unit.text },
          });
        }
      }
    }
    return missing;
  }
  const cached = loadCacheKeys(locale, "api");
  const missing: Missing[] = [];
  for (const file of walkMarkdown(apiDir)) {
    const units = collectUnits(
      segmentMarkdown(readFileSync(file, "utf8"), { scope: relative(apiDir, file) }),
    );
    for (const unit of units) {
      if (!isCatalogedApiUnit(unit)) continue;
      if (!cached.has(keyFor("prose", unit.text))) {
        missing.push({
          file: relative(docsRoot, file),
          kind: "prose",
          sample: preview(unit.text),
          unit: { msgctxt: "docs.api:prose", msgid: unit.text },
        });
      }
    }
  }
  for (const { id, term } of GLOSSARY_TERMS) {
    if (!cached.has(keyFor("text", term))) {
      missing.push({ file: `glossary.ts#${id}`, kind: "text", sample: preview(term) });
    }
  }
  return missing;
};

const chromeLeaves = flattenStrings(ENGLISH_UI_STRINGS);

/** Chrome drift: every UI-string leaf (nav/sidebar/CDN picker/etc.) needs a cached translation. */
const chromeDrift = (locale: string): Missing[] => {
  if (chromeLeaves.length === 0) return [];
  const poPath = join(l10nDir, locale, "docs.chrome.po");
  if (existsSync(poPath)) {
    const translated = loadPoTranslatedSet(poPath, (entry) => entry.msgctxt);
    return chromeLeaves
      .filter(({ path }) => !translated.has(`docs.chrome:${path}`))
      .map(({ path, text }) => ({
        file: `.vitepress/i18n.json#${path}`,
        kind: "text",
        sample: preview(text),
        unit: { msgctxt: `docs.chrome:${path}`, msgid: text },
      }));
  }
  const cached = loadCacheKeys(locale, "chrome");
  return chromeLeaves
    .filter(({ text }) => !cached.has(keyFor("text", text)))
    .map(({ path, text }) => ({
      file: `.vitepress/i18n.ts#${path}`,
      kind: "text",
      sample: preview(text),
      unit: { msgctxt: `docs.chrome:${path}`, msgid: text },
    }));
};

const homeUnits = existsSync(homeIndex)
  ? extractFrontmatterUnits(readFileSync(homeIndex, "utf8"), "index.md")
  : [];

/**
 * Home drift: every translatable `docs/index.md` frontmatter value (hero text/tagline, action labels,
 * feature titles and details) needs a cached translation, or the localized home page falls back to
 * showing English copy under a locale route.
 */
const homeDrift = (locale: string): Missing[] => {
  if (homeUnits.length === 0) return [];
  const poPath = join(l10nDir, locale, "docs.home.po");
  if (existsSync(poPath)) {
    const translated = loadPoTranslatedSet(poPath);
    return homeUnits
      .filter((unit) => !translated.has(unit.msgid))
      .map((unit) => ({
        file: unit.reference,
        kind: "text",
        sample: preview(unit.msgid),
        unit: { msgid: unit.msgid },
      }));
  }
  const cached = loadCacheKeys(locale, "home");
  const missing: Missing[] = [];
  for (const unit of homeUnits) {
    if (!cached.has(keyFor("text", unit.msgid))) {
      missing.push({
        file: "index.md",
        kind: "text",
        sample: preview(unit.msgid),
        unit: { msgid: unit.msgid },
      });
    }
  }
  return missing;
};

const demoNames = existsSync(demoDir) ? listDemoNames(demoDir) : [];

/** Demos drift: every demo-local i18n string needs a cached translation. */
const demosDrift = (locale: string): Missing[] => {
  if (demoNames.length === 0) return [];
  const poPath = join(l10nDir, locale, "docs.demos.po");
  if (existsSync(poPath)) {
    const translated = loadPoTranslatedSet(poPath, (entry) => entry.msgctxt);
    const missing: Missing[] = [];
    for (const name of demoNames) {
      const { strings } = loadDemoI18n(join(demoDir, name));
      for (const key of Object.keys(strings)) {
        if (!translated.has(`docs.demos:${name}:${key}`)) {
          missing.push({
            file: `demos/${name}/i18n.json#${key}`,
            kind: "text",
            sample: preview(strings[key]),
            unit: { msgctxt: `docs.demos:${name}:${key}`, msgid: strings[key] },
          });
        }
      }
    }
    return missing;
  }
  const cached = loadCacheKeys(locale, "demos");
  const missing: Missing[] = [];
  for (const name of demoNames) {
    const { strings } = loadDemoI18n(join(demoDir, name));
    for (const text of Object.values(strings)) {
      if (!cached.has(keyFor("text", text))) {
        missing.push({
          file: `demos/${name}/i18n.json`,
          kind: "text",
          sample: preview(text),
          unit: { msgid: text },
        });
      }
    }
  }
  return missing;
};

const reporter = new DriftReporter({
  label: "@pantoken/docs",
  fixCommand: "vp run docs:locales:translate",
});

/**
 * A `Missing.file` is either a real docs-relative path (`guide/foo.md`) or a symbolic
 * `file#anchor` locator (`glossary.ts#tokens`). Annotations need a path GitHub can resolve, so the
 * anchor moves into the detail text and the path is made repo-relative.
 */
const record = (surface: string, locale: string, items: readonly Missing[]): void => {
  for (const item of items) {
    const [path, anchor] = item.file.split("#");
    reporter.add({
      surface,
      locale,
      file: `docs/${path}`,
      detail: `[${item.kind}]${anchor ? ` ${anchor}:` : ""} ${item.sample}`,
      unit: item.unit,
    });
  }
};

const apiGenerated = existsSync(apiDir);
if (!apiGenerated) {
  console.warn(`! docs/api not generated — skipping API drift (run docs:api:en first).`);
}

for (const locale of targets) {
  record("docs.guides", locale, guideDrift(locale));
  record("docs.home", locale, homeDrift(locale));
  record("docs.chrome", locale, chromeDrift(locale));
  record("docs.demos", locale, demosDrift(locale));
  if (apiGenerated) record("docs.api", locale, apiDrift(locale));
}

process.exitCode = reporter.report();
const jsonOutput = process.env.DRIFT_JSON_OUT;
if (jsonOutput) {
  mkdirSync(dirname(jsonOutput), { recursive: true });
  writeFileSync(jsonOutput, `${JSON.stringify(reporter.recordedFindings, null, 2)}\n`);
}

/**
 * Gate for the compatibility manifest. Rebuilds the expected manifest in memory and fails if the
 * committed `compatibility.json` doesn't match — so an upstream bump or a new consumer must
 * regenerate it (`vp run sync:compatibility`) in the same change. Compares the *parsed* objects, so
 * it never fights the JSON formatter over whitespace.
 *
 * @module
 */
import fs from "node:fs/promises";
import path from "node:path";
import { buildCompatibility, type Compatibility } from "./compatibility.ts";

const ROOT = path.resolve(new URL("../../", import.meta.url).pathname);

/** Canonical (key-sorted) JSON, so equality ignores key order and whitespace. */
function canonical(value: unknown): string {
  const sort = (v: unknown): unknown => {
    if (v === null || typeof v !== "object") return v;
    if (Array.isArray(v)) return v.map(sort);
    const o = v as Record<string, unknown>;
    return Object.fromEntries(
      Object.keys(o)
        .sort()
        .map((k) => [k, sort(o[k])]),
    );
  };
  return JSON.stringify(sort(value));
}

async function main(): Promise<void> {
  const expected = await buildCompatibility();

  let committed: Compatibility | null = null;
  try {
    committed = JSON.parse(
      await fs.readFile(path.join(ROOT, "compatibility.json"), "utf8"),
    ) as Compatibility;
  } catch {
    committed = null;
  }

  if (!committed) {
    console.error(
      "✗ compatibility: compatibility.json is missing or unparseable. Run `vp run sync:compatibility` and commit it.",
    );
    process.exitCode = 1;
    return;
  }

  if (canonical(committed) !== canonical(expected)) {
    console.error(
      "✗ compatibility: compatibility.json is stale (upstream pins or consumers changed).",
    );
    console.error(
      "  Run `vp run sync:compatibility` and commit compatibility.json + docs/compatibility.md.",
    );
    process.exitCode = 1;
    return;
  }

  console.log(
    `✓ compatibility: manifest matches (${Object.keys(expected.upstream).length} upstream sources, ${expected.consumers.length} consumers).`,
  );
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
});

