import { extractFrontmatterUnits, parsePo } from "@pantoken/i18n-engine";
import { ENGLISH_UI_STRINGS, NON_ROOT_LOCALES, flattenStrings } from "../.vitepress/i18n.ts";
import { GLOSSARY_TERMS } from "./glossary.ts";
import { listDemoNames, loadDemoI18n } from "./demo-i18n.ts";
import { collectUnits, isCatalogedApiUnit, segmentMarkdown } from "./segment-markdown.ts";
import { keyFor } from "./translation-memory.ts";
import {
  assertGeneratedTranslation,
  generatedFileMarkdown,
} from "../../tools/translation-adapters/src/generated-values.ts";

const docsRoot = join(import.meta.dirname, "..");
const cacheDir = join(docsRoot, "i18n-cache");
const guideDir = join(docsRoot, "guide");
const demoDir = join(docsRoot, "demos");
const apiDir = join(docsRoot, "api");
const homeIndex = join(docsRoot, "index.md");
const l10nDir = join(docsRoot, "..", "l10n");

const targets = NON_ROOT_LOCALES;

interface Missing {
  file: string;
  kind: string;
  sample: string;
  unit?: DriftUnit;
}

const loadPoTranslatedSet = (
  poPath: string,
  keyFn: (entry: { msgctxt?: string; msgid: string; msgstr: string }) => string | undefined = (
    entry,
  ) => entry.msgid,
): Set<string | undefined> => {
  return new Set(
    parsePo(readFileSync(poPath, "utf8"))
      .filter((entry) => !entry.obsolete && !entry.fuzzy && entry.msgstr !== "")
      .map((entry) => {
        if (entry.msgid.includes("{{ptk_code_"))
          assertGeneratedTranslation(entry.msgid, entry.msgstr);
        return entry;
      })
      .map(keyFn),
  );
};

const loadCacheKeys = (locale: string, namespace: string): Set<string> => {
  const path = join(cacheDir, `${locale}.${namespace}.json`);
  if (!existsSync(path)) return new Set();
  const parsed = JSON.parse(readFileSync(path, "utf8")) as { entries?: Record<string, string> };
  return new Set(Object.keys(parsed.entries ?? {}));
};

/** Recursively collect every `.md` file under `dir` (returns `[]` when `dir` doesn't exist). */
export const walkMarkdown = (dir: string): string[] => {
  if (!existsSync(dir)) return [];
  const out: string[] = [];
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) out.push(...walkMarkdown(full));
    else if (full.endsWith(".md")) out.push(full);
  }
  return out;
};

const preview = (text: string): string =>
  text.replace(/\s+/g, " ").trim().slice(0, 60) + (text.length > 60 ? "…" : "");

/** Guide drift: each guide and the compatibility page is one whole-file `markdown` unit. */
const guideDrift = (locale: string): Missing[] => {
  const poPath = join(l10nDir, locale, "docs.guides.po");
  const guideFiles = [...walkMarkdown(guideDir), join(docsRoot, "compatibility.md")].filter(
    existsSync,
  );
  if (existsSync(poPath)) {
    const translated = loadPoTranslatedSet(poPath);
    return guideFiles
      .map((file) => ({
        file: relative(docsRoot, file),
        source: generatedFileMarkdown(readFileSync(file, "utf8")).template,
      }))
      .filter(({ source }) => !translated.has(source))
      .map(({ file, source }) => ({
        file,
        kind: "markdown",
        sample: preview(source),
        unit: { msgid: source },
      }));
  }
  const cached = loadCacheKeys(locale, "guides");
  const missing: Missing[] = [];
  for (const file of guideFiles) {
    const source = generatedFileMarkdown(readFileSync(file, "utf8")).template;
    if (!cached.has(keyFor("markdown", source))) {
      missing.push({
        file: relative(docsRoot, file),
        kind: "markdown",
        sample: preview(source),
        unit: { msgid: source },
      });
    }
  }
  return missing;
};

/** API drift: every `prose` block across the generated EN tree needs a cached `:claude` translation. */
export const apiDrift = (locale: string): Missing[] => {
  const poPath = join(l10nDir, locale, "docs.api.po");
  if (existsSync(poPath)) {
    const translated = loadPoTranslatedSet(
      poPath,
      (entry) => `${entry.msgctxt ?? ""}\0${entry.msgid}`,
    );
    const missing: Missing[] = [];
    for (const file of walkMarkdown(apiDir)) {
      for (const unit of collectUnits(
        segmentMarkdown(readFileSync(file, "utf8"), { scope: relative(apiDir, file) }),
      )) {
        if (!isCatalogedApiUnit(unit)) continue;
        if (!translated.has(`docs.api:${unit.kind}\0${unit.text}`)) {
          missing.push({
            file: relative(docsRoot, file),
            kind: unit.kind,
            sample: preview(unit.text),
            unit: { msgctxt: `docs.api:${unit.kind}`, msgid: unit.text },
          });
        }
      }
    }
    return missing;
  }
  const cached = loadCacheKeys(locale, "api");
  const missing: Missing[] = [];
  for (const file of walkMarkdown(apiDir)) {
    const units = collectUnits(
      segmentMarkdown(readFileSync(file, "utf8"), { scope: relative(apiDir, file) }),
    );
    for (const unit of units) {
      if (!isCatalogedApiUnit(unit)) continue;
      if (!cached.has(keyFor("prose", unit.text))) {
        missing.push({
          file: relative(docsRoot, file),
          kind: "prose",
          sample: preview(unit.text),
          unit: { msgctxt: "docs.api:prose", msgid: unit.text },
        });
      }
    }
  }
  for (const { id, term } of GLOSSARY_TERMS) {
    if (!cached.has(keyFor("text", term))) {
      missing.push({ file: `glossary.ts#${id}`, kind: "text", sample: preview(term) });
    }
  }
  return missing;
};

const chromeLeaves = flattenStrings(ENGLISH_UI_STRINGS);

/** Chrome drift: every UI-string leaf (nav/sidebar/CDN picker/etc.) needs a cached translation. */
const chromeDrift = (locale: string): Missing[] => {
  if (chromeLeaves.length === 0) return [];
  const poPath = join(l10nDir, locale, "docs.chrome.po");
  if (existsSync(poPath)) {
    const translated = loadPoTranslatedSet(poPath, (entry) => entry.msgctxt);
    return chromeLeaves
      .filter(({ path }) => !translated.has(`docs.chrome:${path}`))
      .map(({ path, text }) => ({
        file: `.vitepress/i18n.json#${path}`,
        kind: "text",
        sample: preview(text),
        unit: { msgctxt: `docs.chrome:${path}`, msgid: text },
      }));
  }
  const cached = loadCacheKeys(locale, "chrome");
  return chromeLeaves
    .filter(({ text }) => !cached.has(keyFor("text", text)))
    .map(({ path, text }) => ({
      file: `.vitepress/i18n.ts#${path}`,
      kind: "text",
      sample: preview(text),
      unit: { msgctxt: `docs.chrome:${path}`, msgid: text },
    }));
};

const homeUnits = existsSync(homeIndex)
  ? extractFrontmatterUnits(readFileSync(homeIndex, "utf8"), "index.md")
  : [];

/**
 * Home drift: every translatable `docs/index.md` frontmatter value (hero text/tagline, action labels,
 * feature titles and details) needs a cached translation, or the localized home page falls back to
 * showing English copy under a locale route.
 */
const homeDrift = (locale: string): Missing[] => {
  if (homeUnits.length === 0) return [];
  const poPath = join(l10nDir, locale, "docs.home.po");
  if (existsSync(poPath)) {
    const translated = loadPoTranslatedSet(poPath);
    return homeUnits
      .filter((unit) => !translated.has(unit.msgid))
      .map((unit) => ({
        file: unit.reference,
        kind: "text",
        sample: preview(unit.msgid),
        unit: { msgid: unit.msgid },
      }));
  }
  const cached = loadCacheKeys(locale, "home");
  const missing: Missing[] = [];
  for (const unit of homeUnits) {
    if (!cached.has(keyFor("text", unit.msgid))) {
      missing.push({
        file: "index.md",
        kind: "text",
        sample: preview(unit.msgid),
        unit: { msgid: unit.msgid },
      });
    }
  }
  return missing;
};

const demoNames = existsSync(demoDir) ? listDemoNames(demoDir) : [];

/** Demos drift: every demo-local i18n string needs a cached translation. */
const demosDrift = (locale: string): Missing[] => {
  if (demoNames.length === 0) return [];
  const poPath = join(l10nDir, locale, "docs.demos.po");
  if (existsSync(poPath)) {
    const translated = loadPoTranslatedSet(poPath, (entry) => entry.msgctxt);
    const missing: Missing[] = [];
    for (const name of demoNames) {
      const { strings } = loadDemoI18n(join(demoDir, name));
      for (const key of Object.keys(strings)) {
        if (!translated.has(`docs.demos:${name}:${key}`)) {
          missing.push({
            file: `demos/${name}/i18n.json#${key}`,
            kind: "text",
            sample: preview(strings[key]),
            unit: { msgctxt: `docs.demos:${name}:${key}`, msgid: strings[key] },
          });
        }
      }
    }
    return missing;
  }
  const cached = loadCacheKeys(locale, "demos");
  const missing: Missing[] = [];
  for (const name of demoNames) {
    const { strings } = loadDemoI18n(join(demoDir, name));
    for (const text of Object.values(strings)) {
      if (!cached.has(keyFor("text", text))) {
        missing.push({
          file: `demos/${name}/i18n.json`,
          kind: "text",
          sample: preview(text),
          unit: { msgid: text },
        });
      }
    }
  }
  return missing;
};

const reporter = new DriftReporter({
  label: "@pantoken/docs",
  fixCommand: "vp run docs:locales:translate",
});

/**
 * A `Missing.file` is either a real docs-relative path (`guide/foo.md`) or a symbolic
 * `file#anchor` locator (`glossary.ts#tokens`). Annotations need a path GitHub can resolve, so the
 * anchor moves into the detail text and the path is made repo-relative.
 */
const record = (surface: string, locale: string, items: readonly Missing[]): void => {
  for (const item of items) {
    const [path, anchor] = item.file.split("#");
    reporter.add({
      surface,
      locale,
      file: `docs/${path}`,
      detail: `[${item.kind}]${anchor ? ` ${anchor}:` : ""} ${item.sample}`,
      unit: item.unit,
    });
  }
};

const apiGenerated = existsSync(apiDir);
if (!apiGenerated) {
  console.warn(`! docs/api not generated — skipping API drift (run docs:api:en first).`);
}

for (const locale of targets) {
  record("docs.guides", locale, guideDrift(locale));
  record("docs.home", locale, homeDrift(locale));
  record("docs.chrome", locale, chromeDrift(locale));
  record("docs.demos", locale, demosDrift(locale));
  if (apiGenerated) record("docs.api", locale, apiDrift(locale));
}

process.exitCode = reporter.report();
const jsonOutput = process.env.DRIFT_JSON_OUT;
if (jsonOutput) {
  mkdirSync(dirname(jsonOutput), { recursive: true });
  writeFileSync(jsonOutput, `${JSON.stringify(reporter.recordedFindings, null, 2)}\n`);
}

