  expect(escapeBareHtmlTags("Use ``a `<li>` b`` here.")).toBe("Use ``a `<li>` b`` here.");
  expect(escapeBareHtmlTags("```\n<dialog>\n```")).toBe("```\n<dialog>\n```");
});

