  writeFileSync(join(repo, "packages/scaffold/templates/react/README.md"),
    "<!-- pantoken-generated-values -->\n| Package | Version |\n| --- | --- |\n| `pkg` | `1.0` |\n");
  runExtractContent(config, repo, "scaffold.readme");
  expect(() => runRenderContent(config, repo, "scaffold.readme", "hu"))
    .toThrow("missing reviewed generated-value translation");
});

