    files.set(join(root, "l10n", locale, "docs.guides.po"),
      serializePo([entry(compatibility, compatibility.replace("Support", `${locale} support`))]));
    files.set(join(root, "l10n", locale, "docs.api.po"),
      serializePo([entry(template, template.replace("Target:", `${locale} target:`), "docs.api:prose")]));
