  expect(result.get(keyFor("text", "yyyy-mm-dd"))).toBe("yyyy-mm-dd");
  expect(memory.misses).toBe(1);
  expect(
    warnSpy.mock.calls.some((c: unknown[]) => String(c[0]).includes("looks untranslated")),
