test("keeps API identifiers and code-shaped prose verbatim", async () => {
  const { isRequiredVerbatimApiUnit } = await import("./build-api-locales.ts");

  for (const source of [
    "AggregateOptions",
    "buildThemeCss",
    "canvas-theme-editor",
    "Token",
