      const remaining = references.filter((reference) => !matched.includes(reference));
      return [
        ...matched.map((scope) => ({ entry: { ...entry, references: [scope] }, scope })),
        ...(remaining.length > 0
          ? [{ entry: { ...entry, references: remaining }, skip: true }]
          : []),
      ];
    },
  );
