    })
    .join("");
  const revived = migratedCatalog.filter((entry) => !entry.obsolete && !emitted.has(key(entry)));
  if (revived.length === 0) return catalog;
  return `${catalog.trimEnd()}\n\n${serializePo(revived).split("\n\n").slice(1).join("\n\n")}`;
