  requiredVerbatimSources?: ReadonlySet<string>;
  /** Fallback policy for source-identical translations by locale. */
  defaultVerbatim?: VerbatimPolicy;
  /** Locale resolved against {@link defaultVerbatim}. */
  locale?: string;
