  expect(logSpy.mock.calls.some((c: unknown[]) => String(c[0]).includes("1/3 f0.md"))).toBe(true);
  expect(logSpy.mock.calls.some((c: unknown[]) => String(c[0]).includes("3/3 f2.md"))).toBe(true);
