import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";
import { parsePo, type PoEntry } from "@pantoken/i18n-engine";
import {
  generatedFileMarkdown,
  restoreGeneratedMarkdown,
